// spec: specs/search-header-cta.md (1.6, 1.7) · кейс: .qa/tests/search-header-cta/PUBLISH-01.md
// seed: tests/seed.spec.ts (гость) и tests/seed.user.spec.ts (user — /addbusiness гостя уводит на /auth) · Android (Pixel 7).
// Прод, только просмотр: «פרסם עסק» не нажимается, проверяется ссылка.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, publishLink, categoryUrl, queryUrl } from './search-cta.helpers';

test.use({ serviceWorkers: 'block' });

const PAGES = ['/', '/search', categoryUrl(), queryUrl(), '/packages'];

test.describe('«פרסם עסק» в мобильной шапке', () => {
  test('Гость: «פרסם עסק» в шапке на главной, /search, категории, поиске и /packages #839121 @android @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    for (const p of PAGES) {
      await page.goto(p);
      await expect(publishLink(page), `«פרסם עסק» в шапке: ${p}`).toBeVisible();
      await expect(publishLink(page), `«פרסם עסק» ведёт на публикацию: ${p}`).toHaveAttribute('href', '/addbusiness');
    }
  });

  test.describe('вошедший', () => {
    test.use({ storageState: '../auth/user.json' });

    test('Вошедший: на странице публикации /addbusiness «פרסם עסק» в шапке нет #839121 @android @prod-safe', async ({ page, context }) => {
      await prepareReadOnly(context, true);
      await page.goto('/packages');
      await expect(page.locator('header').getByText('התחברות'), 'user вошёл (сессия жива)').toHaveCount(0);
      await expect(publishLink(page), 'контроль: на /packages кнопка есть').toBeVisible();
      await page.goto('/addbusiness');
      await expect(page, 'вошедшего не уводит на вход').toHaveURL(/\/addbusiness/);
      await expect(page.getByRole('heading', { name: 'פרטים על העסק' }), 'страница публикации загрузилась').toBeVisible({ timeout: 30_000 });
      await expect(publishLink(page), 'на /addbusiness «פרסם עסק» в шапке нет').toHaveCount(0);
    });
  });
});
